<?php declare(strict_types=1); namespace App\Http\Controllers\Pmbm; use App\Enums\Pmbm\ApplicantStatus; use App\Http\Controllers\Controller; use App\Http\Requests\Pmbm\StoreApplicantRequest; use App\Models\AcademicYear; use App\Models\Pmbm\PmbmApplicant; use App\Services\Pmbm\PmbmRegistrationService; use Illuminate\Http\{RedirectResponse,Request}; use Illuminate\View\View;
class ApplicantController extends Controller { public function index(Request $r):View{$q=PmbmApplicant::with('academicYear');if($r->filled('status'))$q->where('status',$r->input('status'));if($s=$r->string('search')->trim()->toString())$q->where(fn($x)=>$x->where('registration_number','like',"%$s%")->orWhere('full_name','like',"%$s%")->orWhere('nik','like',"%$s%"));return view('pmbm.admin.index',['applicants'=>$q->latest()->paginate(15)->withQueryString(),'statuses'=>ApplicantStatus::cases()]);} public function create():View{return view('pmbm.admin.form',['years'=>AcademicYear::orderByDesc('starts_at')->get()]);} public function store(StoreApplicantRequest $r,PmbmRegistrationService $s):RedirectResponse{$a=$s->submit($r->validated(),'offline',$r->user());return redirect()->route('pmbm.applicants.show',$a)->with('status','Pendaftaran offline berhasil dibuat.');} public function show(Request $r,PmbmApplicant $applicant):View{$applicant->load(['documents','histories','academicYear','student']);$sensitive=$r->user()->can('pmbm.applicant.view-sensitive');return view('pmbm.admin.show',compact('applicant','sensitive'));} public function verify(Request $r,PmbmApplicant $applicant,PmbmRegistrationService $s):RedirectResponse{$r->validate(['note'=>'nullable|string|max:1000']);$s->transition($applicant,ApplicantStatus::Verified,$r->user(),$r->input('note','Berkas terverifikasi.'));return back()->with('status','Berkas dinyatakan terverifikasi.');} public function decide(Request $r,PmbmApplicant $applicant,PmbmRegistrationService $s):RedirectResponse{$d=$r->validate(['decision'=>'required|in:accepted,waitlisted,rejected','note'=>'nullable|string|max:1000']);$s->transition($applicant,ApplicantStatus::from($d['decision']),$r->user(),$d['note']??'Keputusan PMBM ditetapkan.');return back()->with('status','Keputusan PMBM disimpan.');} public function enroll(Request $r,PmbmApplicant $applicant,PmbmRegistrationService $s):RedirectResponse{$student=$s->enroll($applicant,$r->user());return redirect()->route('students.show',$student)->with('status','Calon murid berhasil dikonversi menjadi siswa.');} }
